// ===========================================================================
//  NHẬP 7 THÔNG SỐ (sửa rồi bấm Execute workflow)
// ===========================================================================
const NAV       = 186922;  // Tài sản ròng - NGHÌN ĐỒNG (app VietinBank hiện "186,922")
const TICKER    = 'BID';   // Mã
const ENTRY     = 42.0;    // Giá dự định VÀO (nghìn đồng, vd 42 = 42.000đ)
const STOP      = 39.0;    // Giá CẮT LỖ (BẮT BUỘC, phải < giá vào)
const TARGET    = 46.0;    // Giá MỤC TIÊU (0 = bỏ qua R:R)
const RISK_PCT  = 1.5;     // % tài khoản chấp nhận MẤT mỗi lệnh (khuyên 1-2%)
const MAX_POS_PCT = 20;    // Trần % NAV cho 1 vị thế (chống tất tay)
// ===========================================================================

const fmtM = (k) => (k / 1000).toFixed(1) + ' triệu';
const fmtD = (k) => Math.round(k * 1000).toLocaleString('vi-VN') + 'đ';

let msg;
if (!(STOP < ENTRY)) {
  msg = '🧮 *POSITION SIZING — ' + TICKER + '*\n\n⚠️ *Lỗi nhập liệu*: Giá cắt lỗ (' + STOP + ') phải THẤP HƠN giá vào (' + ENTRY + '). '
      + 'Kỷ luật #1: không có cắt lỗ thì không tính khối lượng.';
} else {
  const riskBudgetK   = NAV * RISK_PCT / 100;        // tiền chịu mất (nghìn)
  const riskPerShareK = ENTRY - STOP;                // rủi ro / cổ phiếu (nghìn)
  const sharesByRisk  = Math.floor(riskBudgetK / riskPerShareK / 100) * 100;
  const sharesByCap   = Math.floor(NAV * MAX_POS_PCT / 100 / ENTRY / 100) * 100;
  const shares        = Math.max(0, Math.min(sharesByRisk, sharesByCap));
  const cappedByPos   = sharesByCap < sharesByRisk;

  const posValK     = shares * ENTRY;
  const posPct      = posValK / NAV * 100;
  const realRiskK   = shares * riskPerShareK;
  const realRiskPct = realRiskK / NAV * 100;
  const rr          = TARGET > ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;

  const L = [];
  L.push('🧮 *POSITION SIZING — ' + TICKER + '*');
  L.push('_Vào ' + fmtD(ENTRY) + ' · Cắt lỗ ' + fmtD(STOP) + (TARGET > 0 ? ' · Mục tiêu ' + fmtD(TARGET) : '') + '_');
  L.push('_NAV ' + fmtM(NAV) + ' · rủi ro cho phép ' + RISK_PCT + '%/lệnh_');
  L.push('');
  if (shares <= 0) {
    L.push('→ *Không nên vào*: khoảng cách cắt lỗ quá rộng so với mức rủi ro cho phép — khối lượng tính ra < 1 lô.');
  } else {
    L.push('→ *MUA: ' + shares.toLocaleString('vi-VN') + ' cổ phiếu* (' + (shares / 100) + ' lô)');
    L.push('→ Giá trị vị thế: *' + fmtM(posValK) + '* (' + posPct.toFixed(1) + '% NAV)' + (cappedByPos ? ' _(chạm trần ' + MAX_POS_PCT + '%)_' : ''));
    L.push('→ Rủi ro thực nếu chạm cắt lỗ: *' + fmtM(realRiskK) + '* (' + realRiskPct.toFixed(2) + '% NAV)');
    if (rr !== null) L.push('→ *R:R = ' + rr.toFixed(2) + '* — lãi kỳ vọng ' + rr.toFixed(2) + 'đ cho mỗi 1đ rủi ro');
  }
  L.push('');
  const W = [];
  if (RISK_PCT > 3) W.push('Rủi ro/lệnh ' + RISK_PCT + '% là CAO — khuyên 1-2%.');
  if (rr !== null && rr < 2 && shares > 0) W.push('R:R < 2 — lãi/rủi ro hơi mỏng. PTJ khuyên ≥2-3:1; cân nhắc chờ giá vào tốt hơn hoặc mục tiêu xa hơn.');
  if (cappedByPos && shares > 0) W.push('Vị thế bị giới hạn bởi trần ' + MAX_POS_PCT + '% NAV (chống tập trung 1 mã).');
  if (W.length) L.push('⚠️ ' + W.join('\n⚠️ '));
  L.push('');
  L.push('_Kỷ luật: định cắt lỗ TRƯỚC khi tính khối lượng · không trung bình giá xuống · KHÔNG phải khuyến nghị_');
  msg = L.join('\n');
}

return [{ json: { message: msg } }];
